            text: `Действием вы можете переполнить тело Вуалью и на 1к4 раунда стать воплощением её ужаса.

• Один раз в ход, нанося урон, вы можете израсходовать кости хитов числом до модификатора Телосложения и добавить выпавшее значение к урону.
• Вы получаете сопротивление дробящему, колющему и рубящему урону от немагических атак.
• Ваше перемещение не провоцирует атак.

Один раз в ход, пока эффект активен, вы можете не тратя действия пожертвовать 1 пункт Искры, чтобы продлить его ещё на раунд.`
