      ['Таинственный арканум', SRC, '11-й уровень', `Покровитель дарует вам **арканум** — заклинание 6 круга из списка колдуна, которое вы творите **один раз без ячейки**, восстанавливая его на продолжительном отдыхе.

Вы получаете ещё по аркануму на **13** (7 круг), **15** (8 круг) и **17** (9 круг) уровнях. При повышении уровня один арканум можно заменить другим заклинанием того же круга.`],
      ['Эпическая черта', SRC, '19-й уровень', 'Вы получаете **эпическую черту** или другую подходящую черту (рекомендуется [Дар судьбы](/dnd55e/feats?feat=fate)).'],
      ['Таинственный мастер', SRC, '20-й уровень', 'Когда вы используете **Магическую хитрость**, вы восстанавливаете **все** потраченные ячейки Магии договора.']
