              ['Захват трёх пальцев — 1 очко духа', 'Следующий спасбросок цели в течение 1 минуты или до окончания Захвата совершается с помехой.'],
              ['Ураганный бросок Кобры — 2 очка духа', 'Вы бросаете цель через себя. Она получает 4к6 урона силовым полем + урон, равный броску вашей Кости боевых искусств. Захват заканчивается, а цель получает состояние **Лежащий ничком**.']
