    features: [
      ['Напевы', SRC_TL, '1-й уровень', `Заклинания шамана называются напевами. У шамана нет фокусировки — есть голос.

Голос Шамана. Каждый напев требует только вербального компонента. Если у напева есть материальный компонент со стоимостью, он всё равно требуется. Существо, которое вас не слышит — в том числе **Оглохшее**, — не может быть целью вашего напева и не подвергается его эффектам, даже если попадает в область. Вы не можете сотворять напевы, будучи **Недееспособным** или иначе лишённым возможности говорить.

Шёпоты. Вы знаете 2 заговора-шёпота из списка напевов шамана. Их число растёт по столбцу «Шёп.». При получении уровня в этом классе вы можете заменить один шёпот другим.

Ячейки напевов. Таблица класса показывает число ячеек для напевов 1+ уровня. Все потраченные ячейки восстанавливаются после **продолжительного отдыха**.

Подготовленные напевы. На 1-м уровне выберите 4 напева 1-го уровня из списка напевов шамана. Их число растёт по столбцу «Напевы»; уровень напева не может превышать уровень вашей самой высокой ячейки. При получении уровня в этом классе вы можете заменить один подготовленный напев другим. Напевы вашей мудры всегда подготовлены и в это число не входят.

Базовая характеристика. **Интеллект** — ваша заклинательная характеристика для напевов.

Сл спасброска = 8 + бонус мастерства + модификатор Интеллекта

Модификатор броска атаки = бонус мастерства + модификатор Интеллекта

Ритуалы. Подготовленный напев с ключевым словом «ритуал» вы можете сотворить как ритуал.`],

      ['Призванный Духами', SRC_TL, '1-й уровень', `Духи призвали вас, и вы слышите их прежде, чем научитесь их впускать.

**Напев Оси Мира** и **Напев Видения** всегда подготовлены для вас, не входят в число подготовленных напевов, и вы можете сотворять их как ритуалы, даже не имея свободных ячеек.

Вы понимаете речь малых духов и владеете одним редким языком на ваш выбор.

Действием **Изучение** вы определяете, есть ли в пределах 30 футов дух, освящённое место (обо) или место, где за последние 24 часа оборвалась нить судьбы существа.

Голос места. Потратив 1 минуту, вы обращаетесь к духам места, где находитесь, и задаёте один вопрос о том, что здесь произошло за последний месяц. Духи отвечают не словами, а образом, звуком или запахом; если они не знают ответа или места здесь нет — молчат. Один раз между короткими или продолжительными отдыхами.`],

      ['Удержание Духов', SRC_TL, '2-й уровень', `Выберите духов, требованиям удержания которых вы соответствуете; их число указано в столбце «Духи». При получении уровня в этом классе вы можете заменить одного удерживаемого духа другим.

Напевы Духов. Пока вы удерживаете духа, вы можете использовать его Напев Духа, потратив одно использование Напевов Духов. Их число указано в столбце «Н. Духов»; все использования восстанавливаются после **короткого или продолжительного отдыха**.

Сл спасбросков от Напевов Духов равна Сл ваших напевов. Духи — воплощение своей силы: эффекты, ограничивающие магию, на них не действуют.`],

      ['Одержимость Духом', SRC_TL, '2-й уровень', `Бонусным действием выберите удерживаемого духа и станьте одержимы им на 1 минуту, получая эффекты из его описания. Если Напев Духа этого духа требует бонусного действия, вы можете применить его как часть того же бонусного действия.

Вы можете завершить одержимость бонусным действием. Одержимость не требует концентрации и не заканчивается досрочно.

Каждым конкретным духом вы можете стать одержимы один раз. Все использования восстанавливаются после продолжительного отдыха; после короткого отдыха вы восстанавливаете возможность стать одержимым одним духом на ваш выбор.

До 15-го уровня вы можете быть одержимы одновременно только одним духом, не считая постоянных одержимостей от Ока Предзнаменования и Связи с Духом.`],

      ['Сосуд Духа', SRC_TL, '2-й уровень', `Дух укрепляет плоть, которую занимает. Ваше тело — не мишень, а сосуд, и пока в нём кто-то есть, оно держит удар.

• Пока вы одержимы хотя бы одним духом, ваш КД увеличивается на 2.
• Входя в одержимость, вы получаете временные хиты, равные вашему уровню шамана + модификатор Телосложения. Постоянные одержимости от Ока Предзнаменования, Могучего Ока и Связи с Духом обновляют эти временные хиты после короткого или продолжительного отдыха.`],

      ['Мудра Шамана', SRC_TL, '3-й уровень', 'Мудра дарует силу навыкам шамана: это жесты, движения или ритмический танец, собирающий силы духов в желаемую форму. Выберите мудру — **Шамаса**, **Ману**, **Пустоты** или **Безумия**. Мудра даёт умения на 3, 6, 10 и 14 уровнях и таблицу всегда подготовленных напевов на 3, 7, 11, 15 и 17 уровнях.'],

      ['Судьба Шамана', SRC_TL, '3-й уровень', `Вы можете расширить границы своей воли, используя Кость Нити. Ваша Кость Нити — 1к6Н; её размер растёт по столбцу «Кость Нити». Способы её применения определяются вашей мудрой.

Взрыв. Если на Кости Нити выпало максимальное значение, бросьте эту кость ещё раз и прибавьте результат; взрывы повторяются без ограничения.

Взрыв не превращает попадание в критическое, и при критическом попадании удваивается только исходное число Костей Нити — выпавшие взрывы не удваиваются.`],

      ['Повышение характеристик', SRC_TL, '4-й уровень', 'Вы получаете черту Повышение характеристик или другую подходящую черту. Это умение повторяется на 8, 12 и 16 уровнях.'],

      ['Око Предзнаменования', SRC_TL, '5-й уровень', `Духи распознают вас как точку фокусировки линий судьбы и стараются держаться рядом.

Выберите малого духа. Вы удерживаете его, он не входит в число удерживаемых духов, и вы **постоянно им одержимы**. Выбор можно изменить при получении уровня в этом классе.

Постоянная одержимость не тратит использований Одержимости Духом и не заканчивается. Если пассивная способность духа даёт истекающее преимущество (например, временные хиты), оно возобновляется после короткого или продолжительного отдыха. Напев Духа постоянно удерживаемого духа по-прежнему тратит использование Напевов Духов.`],

      ['Нить Напева', SRC_TL, '7-й уровень', `Дух может держать напев вместо вас, пока вы поёте следующий.

Пока вы одержимы духом, вы можете передать ему концентрацию на одном своём напеве (действие не требуется). Дух поддерживает этот напев, и вы освобождаетесь для концентрации на другом. Одновременно духам можно доверить только один напев.

Духу можно доверить напев, уровень которого не превышает половину вашего уровня шамана, округляя вниз. Самые сильные напевы дух не удержит — их вы держите сами.

Дух не совершает спасбросков на концентрацию: доверенный напев заканчивается, когда заканчивается одержимость этим духом, когда вы становитесь **Недееспособны**, когда вы доверяете духу другой напев или когда вы завершаете напев по своей воле. Поскольку одержимость длится 1 минуту, доверенный напев не может длиться дольше.`],

      ['Могучее Око Предзнаменования', SRC_TL, '9-й уровень', 'Выберите ещё одного малого духа, которым вы постоянно одержимы, на условиях Ока Предзнаменования.'],

      ['Улучшение Воли Шамана', SRC_TL, '11-й уровень', `Вы можете кардинально менять ситуацию одной своей волей. Ваша Кость Нити взрывается при результатах 5 и 6.

Кроме того, ваш голос преодолевает магическую тишину: заклинания и эффекты, создающие область, в которой невозможен звук, не мешают вам сотворять напевы. Существо, которое всё равно вас не слышит, по-прежнему не подвержено вашим напевам.

*Мудра Безумия изменяет первый абзац этого умения.*`],

      ['Связь с Духом', SRC_TL, '13-й уровень', 'Выберите среднего духа. Вы удерживаете его сверх лимита и постоянно им одержимы, на условиях Ока Предзнаменования.'],

      ['Хор Духов', SRC_TL, '15-й уровень', `Вы можете быть одержимы двумя духами одновременно, не считая постоянных одержимостей; вход во вторую одержимость требует отдельного бонусного действия.

Кроме того, вы можете доверить напев каждому из них: теперь духи держат до двух напевов, пока вы концентрируетесь на третьем.`],

      ['Древний Зов', SRC_TL, '17-й уровень', `Ваша мудра даёт вам напев 9-го уровня; он всегда подготовлен и не входит в число подготовленных напевов.

Кроме того, один раз между продолжительными отдыхами вы можете стать одержимы древним духом, не тратя использования Одержимости Духом.`],

      ['Мастерство Напевов', SRC_TL, '18-й уровень', 'Выберите один подготовленный напев 1-го уровня и один 2-го уровня. Вы можете сотворять их на их базовом уровне, не тратя ячейку. Выбор можно изменить, потратив 1 час размышлений в конце продолжительного отдыха.'],

      ['Эпический дар', SRC_TL, '19-й уровень', `Вы получаете черту категории «Эпический дар» или другую черту, требованиям которой соответствуете. Профильный вариант:

Эпический дар Нити. Ваш Интеллект увеличивается на 1 (максимум 30). Один раз между продолжительными отдыхами, увидев результат броска к20 у себя или у существа в пределах 60 футов, вы можете бросить Кость Нити и прибавить или вычесть выпавшее число.`],

      ['Ткач Судьбы', SRC_TL, '20-й уровень', `Вы становитесь едины с миром духов, и поток судьбы подчиняется вам.

• Когда вы совершаете бросок Инициативы, вы восстанавливаете все использования Одержимости Духом. Один раз между продолжительными отдыхами.
• Дважды между продолжительными отдыхами, увидев результат к20 у существа в пределах 60 футов (включая себя), вы можете объявить этот результат равным 20 или 1.`]
    ]
